INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_FOLK_CATHOLIC','Modern Latin American Folk Catholicism',1900,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_CHESNUT_DEVOTED_DEATH','secondary scholarship','R. Andrew Chesnut, Devoted to Death: Santa Muerte, the Skeleton Saint (Oxford University Press, 2012; rev. 2017)','Santa Muerte and the comparative cult of personified Death; Latin American folk sanctity'),
 ('SRC_GRAZIANO_CULTURES_DEVOTION','secondary scholarship','Frank Graziano, Cultures of Devotion: Folk Saints of Spanish America (Oxford University Press, 2007)','Unofficial folk saints of Spanish America: Difunta Correa, San La Muerte, Niño Fidencio, Sarita Colonia, and others')
INSERT INTO _e VALUES
 ('ENT_FCS_FOLK_SAINTS','Latin American Folk Saints','Saint collective','collective','Folk Catholic','Vernacular sanctity, popular canonization, miraculous intercession','B','Hub for the folk-canonized (popular, Rome-unrecognized) intercessory figures of modern Latin American vernacular Catholicism; well attested ethnographically.'),
 ('ENT_FCS_SANTA_MUERTE','Santa Muerte','Folk saint','folk_saint','Folk Catholic','Death personified, protection, healing, justice, love, devotion of the marginalized','B','Mexican folk ''saint'' (Holy Death), a skeletal female personification of death venerated since at least the mid-20th c. with mass public shrines (Tepito); not recognized by Rome; imagery descends from the personified Grim Reaper / Death.'),
 ('ENT_FCS_SAN_LA_MUERTE','San La Muerte','Folk saint','folk_saint','Folk Catholic','Death personified, protection, oaths, sudden help','B','Argentine/Paraguayan/Guaraní-zone male folk saint of personified Death (skeletal figure); publicly venerated in the Litoral region; Rome-unrecognized; cognate of the broader Death-saint devotion.'),
 ('ENT_FCS_MAXIMON','Maximón (San Simón)','Folk saint','folk_saint','Folk Catholic','Fortune, fertility, protection, intercession, bargains and vows, Maya-Catholic intercession','B','Guatemalan Maya-Catholic syncretic figure of the highlands (esp. Santiago Atitlán, San Andrés Itzapa), publicly identified with St. Simon and an Indigenous Maya ancestral/Mam figure; an effigy receives offerings of tobacco and liquor. Only the public devotion is modeled.'),
 ('ENT_FCS_JESUS_MALVERDE','Jesús Malverde','Folk saint','folk_saint','Folk Catholic','Protection of the poor and travelers, intercession, popular justice','C','Sinaloan (Mexico) folk saint, said to be an early-20th-c. bandit-benefactor executed c.1909; venerated at a Culiacán chapel; not recognized by Rome. Modeled neutrally as a publicly attested devotion.'),
 ('ENT_FCS_NINO_FIDENCIO','Niño Fidencio','Folk saint','folk_saint','Folk Catholic','Healing, spirit mediumship, popular intercession','B','José Fidencio Constantino Síntora (1898–1938), a celebrated curandero of Espinazo, Nuevo León (Mexico); posthumously venerated as a folk healer-saint with a living devotional movement (fidencistas); Rome-unrecognized.'),
 ('ENT_FCS_SARITA_COLONIA','Sarita Colonia','Folk saint','folk_saint','Folk Catholic','Protection of migrants, the poor and the marginalized, intercession','B','Sara Colonia Zambrano (1914–1940), a poor migrant woman in Callao, Peru; posthumously venerated as a folk saint of the urban marginalized; Rome-unrecognized.'),
 ('ENT_FCS_DIFUNTA_CORREA','Difunta Correa','Folk saint','folk_saint','Folk Catholic','Protection of travelers and the desperate, miraculous nourishment, intercession','B','Argentine folk saint (Deolinda Correa), a 19th-c. woman said to have died of thirst in the San Juan desert while her nursing infant survived; major roadside shrine at Vallecito; Rome-unrecognized.'),
 ('ENT_FCS_SAN_PASCUALITO','San Pascualito','Folk saint','folk_saint','Folk Catholic','Death personified, healing, protection from epidemic, intercession','C','Guatemalan/Chiapas Maya-Catholic skeletal folk saint of Death, publicly associated by name with the canonical St. Paschal Baylón but venerated as a personified-Death figure; centered at Olintepeque and Chiapas; Rome-unrecognized in this form.');
