INSERT INTO _r VALUES
 ('ENT_FCS_SANTA_MUERTE','member_of','ENT_FCS_FOLK_SAINTS','high','Santa Muerte is the most widely venerated of the Latin American folk saints (Chesnut).'),
 ('ENT_FCS_SAN_LA_MUERTE','member_of','ENT_FCS_FOLK_SAINTS','high','San La Muerte is a folk-canonized intercessory figure of the Litoral region (Graziano).'),
 ('ENT_FCS_MAXIMON','member_of','ENT_FCS_FOLK_SAINTS','high','Maximón/San Simón is a publicly venerated Guatemalan folk saint.'),
 ('ENT_FCS_JESUS_MALVERDE','member_of','ENT_FCS_FOLK_SAINTS','high','Jesús Malverde is a Sinaloan folk saint (Graziano).'),
 ('ENT_FCS_NINO_FIDENCIO','member_of','ENT_FCS_FOLK_SAINTS','high','Niño Fidencio heads a living folk-saint devotion (fidencismo).'),
 ('ENT_FCS_SARITA_COLONIA','member_of','ENT_FCS_FOLK_SAINTS','high','Sarita Colonia is a Peruvian folk saint of the marginalized (Graziano).'),
 ('ENT_FCS_DIFUNTA_CORREA','member_of','ENT_FCS_FOLK_SAINTS','high','Difunta Correa is a major Argentine folk saint (Graziano).'),
 ('ENT_FCS_SAN_PASCUALITO','member_of','ENT_FCS_FOLK_SAINTS','high','San Pascualito is a Guatemalan/Chiapas folk saint of Death.'),
 ('ENT_FCS_SANTA_MUERTE','reception_of','ENT_DEATH','high','Santa Muerte''s skeletal scythe-bearing iconography is a devotional reception of personified Death / the Grim Reaper (Chesnut, Devoted to Death).'),
 ('ENT_FCS_SAN_LA_MUERTE','reception_of','ENT_DEATH','high','San La Muerte is likewise a personification of Death received as a folk saint (Graziano).'),
 ('ENT_FCS_SAN_PASCUALITO','reception_of','ENT_DEATH','medium','San Pascualito is venerated as a skeletal personification of Death in Maya-Catholic devotion.'),
 ('ENT_FCS_SAN_LA_MUERTE','aligned_with','ENT_FCS_SANTA_MUERTE','medium','San La Muerte (Southern Cone) and Santa Muerte (Mexico) are cognate folk personifications of Death venerated as saints (Chesnut).'),
 ('ENT_FCS_MAXIMON','syncretized_with','ENT_NT_SIMON_ZEALOT','medium','Maximón is publicly identified as ''San Simón,'' overlaying the apostle Simon onto a Maya ancestral figure (Graziano); only the public identification is modeled.'),
 ('ENT_FCS_JESUS_MALVERDE','aligned_with','ENT_JESUS_CHRIST','low','Devotees liken Malverde''s protective benefaction to a Christ-like ''generous bandit'' figure; the popular name evokes Jesus, though no formal identification exists (Graziano).'),
 ('ENT_FCS_NINO_FIDENCIO','aligned_with','ENT_JESUS_CHRIST','low','Fidencista devotion publicly frames Niño Fidencio''s healing ministry in imitatio Christi terms (Graziano).'),
 ('ENT_FCS_SARITA_COLONIA','aligned_with','ENT_SAINT_MARY','low','Sarita Colonia''s public cult casts her as a compassionate maternal intercessor for the marginalized, modeled on Marian devotion (Graziano).'),
 ('ENT_FCS_DIFUNTA_CORREA','aligned_with','ENT_SAINT_MARY','low','The Difunta Correa devotion centers on the miraculously nursing mother, drawing on Marian maternal-intercessor imagery (Graziano).'),
 ('ENT_FCS_FOLK_SAINTS','reception_of','ENT_SAINT_MARY','medium','Latin American folk sanctity adapts the Catholic cult of the saints and Marian intercession into vernacular, locally canonized figures (Graziano).');
